package io.ecosync.rest;

import io.ecosync.credentials.RestCredentials;
import io.ecosync.organizations.TenantDirectory;
import io.ecosync.restcontract.*;
import java.util.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import static io.ecosync.restcontract.RestJson.*;

/** Tenant authority only. No HTTP client for source APIs exists in this process. */
@Service @ConditionalOnProperty(name="ecosync.rest.enabled",havingValue="true")
public class RestRegistry {
 public record Registration(String displayName,String baseUrl,String authType,String authHeader,String secret,String document){@Override public String toString(){return "RestRegistration[REDACTED]";}}
 public record Scope(String role,boolean approved){}
 private record Revision(UUID org,UUID id,long version,String base,String auth,String header,UUID credential,String fingerprint,String state,String health){}
 private final JdbcTemplate db;private final TenantDirectory tenants;private final RestCredentials secrets;private final RestAssertions assertions;private final RestGateway gateway;private final TransactionTemplate tx;private final String destinations;private final boolean development;private final OpenApiImporter importer;private final Object[] locks=new Object[64];
 public RestRegistry(JdbcTemplate db,TenantDirectory tenants,RestCredentials secrets,RestAssertions assertions,RestGateway gateway,PlatformTransactionManager transactions,@Value("${ecosync.rest.destinations:}")String destinations,@Value("${ecosync.rest.environment:production}")String environment,@Value("${ecosync.rest.import-bytes:262144}")int bytes,@Value("${ecosync.rest.import-paths:64}")int paths,@Value("${ecosync.rest.import-operations:128}")int operations,@Value("${ecosync.rest.import-nodes:20000}")int nodes){this.db=db;this.tenants=tenants;this.secrets=secrets;this.assertions=assertions;this.gateway=gateway;this.destinations=destinations;development=environment.equals("development");importer=new OpenApiImporter(new OpenApiImporter.Limits(bytes,paths,operations,nodes));tx=new TransactionTemplate(transactions);Arrays.setAll(locks,i->new Object());db.update("UPDATE app.rest_event SET status='INTERRUPTED',ended_at=CURRENT_TIMESTAMP WHERE status='RUNNING'");}
 private Object lock(UUID org,UUID id){return locks[Math.floorMod(Objects.hash(org,id),locks.length)];}
 private List<String> roles(UUID actor,UUID org){return tenants.requireMembership(actor,org).roles();}
 private void admin(UUID actor,UUID org){if(!roles(actor,org).contains("INTEGRATION_ADMIN"))throw new AccessDeniedException("Integration administrator required");}
 private Revision revision(UUID org,UUID id){var rows=db.query("SELECT c.*,i.state,i.health FROM app.rest_connector i JOIN app.rest_configuration c ON c.organization_id=i.organization_id AND c.connector_id=i.id AND c.version=i.configuration_version WHERE i.organization_id=? AND i.id=?",(r,n)->new Revision(org,id,r.getLong("version"),r.getString("base_url"),r.getString("auth_type"),r.getString("auth_header"),r.getObject("credential_id",UUID.class),r.getString("fingerprint"),r.getString("state"),r.getString("health")),org,id);if(rows.size()!=1)throw new AccessDeniedException("Connector unavailable");return rows.getFirst();}
 public long count(UUID actor,UUID org){roles(actor,org);return db.queryForObject("SELECT count(*) FROM app.rest_connector WHERE organization_id=? AND state<>'REVOKED'",Long.class,org);}
 public Map<String,Object> list(UUID actor,UUID org){return list(actor,org,false);}
 public Map<String,Object> list(UUID actor,UUID org,boolean includeRevoked){var roles=roles(actor,org);return Map.of("available",true,"canManage",roles.contains("INTEGRATION_ADMIN"),"items",db.queryForList("SELECT id,display_name,state,health,configuration_version FROM app.rest_connector WHERE organization_id=? AND (? OR state<>'REVOKED') ORDER BY created_at DESC,id LIMIT 128",org,includeRevoked));}
 public Map<String,Object> detail(UUID actor,UUID org,UUID id){roles(actor,org);var r=revision(org,id);var out=new LinkedHashMap<String,Object>(db.queryForMap("SELECT id,display_name,state,health,configuration_version FROM app.rest_connector WHERE organization_id=? AND id=?",org,id));out.put("baseUrl",r.base);out.put("authType",r.auth);out.put("authHeader",r.header);out.put("credentialConfigured",r.credential!=null);out.put("fingerprint",r.fingerprint);out.put("contract",db.queryForObject("SELECT contract::text FROM app.rest_configuration WHERE organization_id=? AND connector_id=? AND version=?",(row,n)->MAPPER.readValue(row.getString(1),Map.class),org,id,r.version));
  out.put("operations",db.query("SELECT id,metadata FROM app.rest_operation WHERE organization_id=? AND connector_id=? AND version=? ORDER BY operation_key",(row,n)->{UUID operation=row.getObject(1,UUID.class);var m=new LinkedHashMap<String,Object>(MAPPER.readValue(row.getString(2),Map.class));m.put("id",operation);m.put("approvals",db.queryForList("SELECT role,status,actor,created_at FROM app.rest_approval WHERE organization_id=? AND operation_id=? ORDER BY created_at DESC LIMIT 20",org,operation));return m;},org,id,r.version));out.put("events",db.queryForList("SELECT id,actor,version,operation_id,kind,status,error_code,started_at,ended_at,duration_ms FROM app.rest_event WHERE organization_id=? AND connector_id=? ORDER BY started_at DESC,id LIMIT 30",org,id));out.put("revisions",db.queryForList("SELECT version,document_fingerprint,fingerprint,created_at FROM app.rest_configuration WHERE organization_id=? AND connector_id=? ORDER BY version DESC LIMIT 20",org,id));return out;
 }
 private OpenApiImporter.Contract validate(Registration r){if(r==null||r.displayName==null||r.displayName.isBlank()||r.displayName.length()>100||r.displayName.chars().anyMatch(Character::isISOControl)||r.document==null)throw new RestFailure("REST_INVALID_ARGUMENTS");RestDestination.check(r.baseUrl,destinations,development);return importer.parse(r.document);}
 private void protect(Registration r,String secret){if(containsSecret(Arrays.asList(r.displayName,r.baseUrl,r.authHeader,read(r.document.getBytes(java.nio.charset.StandardCharsets.UTF_8),1048576)),secret))throw new RestFailure("REST_SECRET_IN_CONTRACT");}
 public Map<String,Object> register(UUID actor,UUID org,Registration input){admin(actor,org);var contract=validate(input);UUID id=UUID.randomUUID();tx.executeWithoutResult(s->{db.execute("SELECT pg_advisory_xact_lock(33819005)");if(db.queryForObject("SELECT count(*) FROM app.rest_connector WHERE state<>'REVOKED'",Integer.class)>=64)throw new RestFailure("REST_LIMIT");RestAuth.configuration(input.authType,input.authHeader,input.secret);protect(input,input.secret);UUID credential=input.authType.equals("NONE")?null:secrets.store(org,new RestCredentials.Secret(input.secret));db.update("INSERT INTO app.rest_connector(organization_id,id,display_name,configuration_version,created_by) VALUES(?,?,?,1,?)",org,id,input.displayName.strip(),actor);insert(actor,org,id,1,credential,input,contract);event(actor,org,id,1,null,"REGISTER","SUCCESS",null);});return detail(actor,org,id);}
 private void insert(UUID actor,UUID org,UUID id,long version,UUID credential,Registration input,OpenApiImporter.Contract contract){String base=RestDestination.parse(input.baseUrl).canonical(),header=Objects.toString(input.authHeader,"").toLowerCase(Locale.ROOT);String fp=hash(Arrays.asList(base,input.authType,header,credential,contract.fingerprint()));db.update("INSERT INTO app.rest_configuration(organization_id,connector_id,version,base_url,auth_type,auth_header,credential_id,document,document_fingerprint,contract,fingerprint,created_by) VALUES(?,?,?,?,?,?,?,?::jsonb,?,?::jsonb,?,?)",org,id,version,base,input.authType,header,credential,MAPPER.writeValueAsString(read(input.document.getBytes(java.nio.charset.StandardCharsets.UTF_8),1048576)),contract.fingerprint(),MAPPER.writeValueAsString(Map.of("title",contract.title(),"version",contract.version(),"openapi",contract.openapi(),"fingerprint",contract.fingerprint())),fp,actor);
  for(var operation:contract.operations())db.update("INSERT INTO app.rest_operation(organization_id,connector_id,version,id,operation_key,supported,metadata,fingerprint) VALUES(?,?,?,?,?,?,?::jsonb,?)",org,id,version,UUID.randomUUID(),operation.operationId(),operation.supported(),MAPPER.writeValueAsString(operation),hash(List.of(fp,operation.fingerprint())));
 }
 public Map<String,Object> revise(UUID actor,UUID org,UUID id,Registration input){admin(actor,org);var contract=validate(input);synchronized(lock(org,id)){var r=revision(org,id);tx.executeWithoutResult(s->{String secret=input.secret;UUID credential=null;if(!input.authType.equals("NONE")){if(secret==null||secret.isEmpty()){if(!input.authType.equals(r.auth)||!Objects.toString(input.authHeader,"").equalsIgnoreCase(r.header)||r.credential==null)throw new RestFailure("REST_AUTH_UNSUPPORTED");secret=secrets.resolve(org,r.credential).value();credential=r.credential;}else credential=secrets.store(org,new RestCredentials.Secret(secret));}RestAuth.configuration(input.authType,input.authHeader,secret);protect(input,secret);if(db.update("UPDATE app.rest_connector SET display_name=?,configuration_version=configuration_version+1,state='DRAFT',health='UNKNOWN',updated_at=CURRENT_TIMESTAMP WHERE organization_id=? AND id=? AND configuration_version=?",input.displayName.strip(),org,id,r.version)!=1)throw new RestFailure("REST_DISABLED");insert(actor,org,id,r.version+1,credential,input,contract);stale(org,id);if(r.credential!=null&&!r.credential.equals(credential))secrets.revoke(org,r.credential);event(actor,org,id,r.version+1,null,"REVISE","SUCCESS",null);});gateway.retire(org,id);}gateway.reconcile();return detail(actor,org,id);}
 private void stale(UUID org,UUID id){db.update("UPDATE app.rest_approval SET status='STALE' WHERE organization_id=? AND status='APPROVED' AND operation_id IN(SELECT id FROM app.rest_operation WHERE organization_id=? AND connector_id=?)",org,org,id);}
 private Map<String,Object> operation(Revision r,UUID id){var rows=db.query("SELECT metadata,fingerprint,supported FROM app.rest_operation WHERE organization_id=? AND connector_id=? AND version=? AND id=?",(row,n)->{var m=new LinkedHashMap<String,Object>(MAPPER.readValue(row.getString(1),Map.class));m.put("approvalFingerprint",row.getString(2));return m;},r.org,r.id,r.version,id);if(rows.size()!=1||!Boolean.TRUE.equals(rows.getFirst().get("supported")))throw new RestFailure("REST_ACCESS_DENIED");return rows.getFirst();}
 private boolean eligible(UUID actor,Revision r,UUID operation){var roles=roles(actor,r.org).stream().filter(x->Set.of("INTEGRATION_ADMIN","USER").contains(x)).toList();if(roles.isEmpty())return false;return db.queryForObject("SELECT count(*)>0 FROM app.rest_operation o JOIN app.rest_approval a ON a.organization_id=o.organization_id AND a.operation_id=o.id AND a.fingerprint=o.fingerprint WHERE o.organization_id=? AND o.connector_id=? AND o.version=? AND o.supported AND a.status='APPROVED' AND a.role=ANY(?::text[]) AND (?::uuid IS NULL OR o.id=?)",Boolean.class,r.org,r.id,r.version,"{"+String.join(",",roles)+"}",operation,operation);}
 public Map<String,Object> inspect(UUID actor,UUID org,UUID id){admin(actor,org);synchronized(lock(org,id)){var r=revision(org,id);if(r.state.equals("REVOKED"))throw new RestFailure("REST_DISABLED");tx.executeWithoutResult(s->{stale(org,id);db.update("UPDATE app.rest_connector SET state='INSPECTED',health='UNKNOWN',updated_at=CURRENT_TIMESTAMP WHERE organization_id=? AND id=?",org,id);event(actor,org,id,r.version,null,"INSPECT","SUCCESS",null);});gateway.retire(org,id);}gateway.reconcile();return detail(actor,org,id);}
 public Map<String,Object> approve(UUID actor,UUID org,UUID id,UUID operation,Scope scope){admin(actor,org);if(scope==null||!Set.of("INTEGRATION_ADMIN","USER").contains(scope.role))throw new RestFailure("REST_INVALID_ARGUMENTS");synchronized(lock(org,id)){var r=revision(org,id);if(!Set.of("INSPECTED","APPROVED","ACTIVE").contains(r.state))throw new RestFailure("REST_DISABLED");var op=operation(r,operation);if(!RestAuth.compatible((List<String>)op.get("authentication"),r.auth,r.header))throw new RestFailure("REST_AUTH_UNSUPPORTED");tx.executeWithoutResult(s->{db.update("UPDATE app.rest_approval SET status='REVOKED' WHERE organization_id=? AND operation_id=? AND role=? AND status='APPROVED'",org,operation,scope.role);db.update("INSERT INTO app.rest_approval(organization_id,id,operation_id,role,fingerprint,status,actor) VALUES(?,?,?,?,?,?,?)",org,UUID.randomUUID(),operation,scope.role,op.get("approvalFingerprint"),scope.approved?"APPROVED":"REVOKED",actor);if(scope.approved&&!r.state.equals("ACTIVE"))db.update("UPDATE app.rest_connector SET state='APPROVED' WHERE organization_id=? AND id=?",org,id);event(actor,org,id,r.version,operation,scope.approved?"APPROVE":"REVOKE_OPERATION","SUCCESS",null);});gateway.retire(org,id);}gateway.reconcile();return detail(actor,org,id);}
 public Map<String,Object> activate(UUID actor,UUID org,UUID id){admin(actor,org);synchronized(lock(org,id)){var r=revision(org,id);if(!r.state.equals("APPROVED")||!r.health.equals("HEALTHY")||!eligible(actor,r,null))throw new RestFailure("REST_DISABLED");db.update("UPDATE app.rest_connector SET state='ACTIVE',updated_at=CURRENT_TIMESTAMP WHERE organization_id=? AND id=?",org,id);event(actor,org,id,r.version,null,"ACTIVATE","SUCCESS",null);}gateway.reconcile();return detail(actor,org,id);}
 public Map<String,Object> disable(UUID actor,UUID org,UUID id,boolean revoke){admin(actor,org);synchronized(lock(org,id)){var r=revision(org,id);if(r.state.equals("REVOKED")&&!revoke)throw new RestFailure("REST_DISABLED");tx.executeWithoutResult(s->{db.update("UPDATE app.rest_connector SET state=?,updated_at=CURRENT_TIMESTAMP WHERE organization_id=? AND id=?",revoke?"REVOKED":"DISABLED",org,id);stale(org,id);if(revoke&&r.credential!=null)secrets.revoke(org,r.credential);db.update("UPDATE app.rest_event SET status='CANCELLED',error_code='REST_CANCELLED',ended_at=CURRENT_TIMESTAMP WHERE organization_id=? AND connector_id=? AND status='RUNNING'",org,id);event(actor,org,id,r.version,null,revoke?"REVOKE":"DISABLE","SUCCESS",null);});gateway.retire(org,id);}gateway.reconcile();return detail(actor,org,id);}
 public Map<String,Object> authorize(String assertion,String mode,UUID requested){var c=assertions.verify(assertion);UUID actor=UUID.fromString((String)c.get("sub")),org=UUID.fromString((String)c.get("org")),id=UUID.fromString((String)c.get("connector"));var r=revision(org,id);roles(actor,org);String action=(String)c.get("action");if(r.version!=((Number)c.get("revision")).longValue()||Set.of("DISABLED","REVOKED").contains(r.state))throw new RestFailure("REST_DISABLED");
  if(mode.equals("LIST")){if(!Set.of("LIST","INVOKE","DESCRIBE").contains(action))throw new RestFailure("REST_ACCESS_DENIED");return Map.of("visible",r.state.equals("ACTIVE")&&eligible(actor,r,null));}
  if(!mode.equals(action)||requested==null||!requested.toString().equals(c.get("operation")))throw new RestFailure("REST_ACCESS_DENIED");var op=operation(r,requested);
  if(mode.equals("TEST")){admin(actor,org);if(!Set.of("APPROVED","ACTIVE").contains(r.state)||!eligible(actor,r,requested)||!RestAuth.compatible((List<String>)op.get("authentication"),r.auth,r.header))throw new RestFailure("REST_ACCESS_DENIED");}
  else if(!Set.of("INVOKE","DESCRIBE").contains(mode)||!r.state.equals("ACTIVE")||!r.health.equals("HEALTHY")||!eligible(actor,r,requested))throw new RestFailure("REST_ACCESS_DENIED");
  UUID execution=UUID.fromString((String)c.get("execution"));if(db.queryForObject("SELECT count(*) FROM app.rest_event WHERE organization_id=? AND connector_id=? AND id=? AND actor=? AND version=? AND operation_id=? AND kind=? AND status='RUNNING'",Integer.class,org,id,execution,actor,r.version,requested,mode)!=1)throw new RestFailure("REST_CANCELLED");
  var m=new LinkedHashMap<String,Object>();m.put("organizationId",org);m.put("connectorId",id);m.put("revision",r.version);m.put("baseUrl",RestDestination.check(r.base,destinations,development).canonical());m.put("authType",r.auth);m.put("authHeader",r.header);m.put("secret",r.credential==null?"":secrets.resolve(org,r.credential).value());m.put("operation",op);return m;
 }
 public Map<String,Object> execute(UUID actor,UUID org,UUID id,UUID operation,UUID execution,Map<String,Object> parameters,String action){roles(actor,org);if(execution==null||parameters==null||!Set.of("TEST","INVOKE","DESCRIBE").contains(action))throw new RestFailure("REST_INVALID_ARGUMENTS");if(action.equals("TEST"))admin(actor,org);var r=revision(org,id);var op=operation(r,operation);if(action.equals("DESCRIBE")){if(!parameters.isEmpty())throw new RestFailure("REST_INVALID_ARGUMENTS");}else RestArguments.target(op,parameters);var args=Map.<String,Object>of("connectorId",id.toString(),"revision",r.version,"operationId",operation.toString(),"parameters",parameters);long started=System.nanoTime();db.update("INSERT INTO app.rest_event(organization_id,connector_id,id,actor,version,operation_id,kind,status) VALUES(?,?,?,?,?,?,?,'RUNNING')",org,id,execution,actor,r.version,operation,action);String assertion=assertions.issue(actor,org,id,r.version,action,execution,operation,hash(args));
  try{authorize(assertion,action,operation);var result=action.equals("TEST")?gateway.inspect(assertion,args):gateway.call(assertion,action.equals("DESCRIBE")?"rest_describe_operation":"rest_invoke_operation",args);synchronized(lock(org,id)){authorize(assertion,action,operation);if(db.update("UPDATE app.rest_event SET status='SUCCESS',ended_at=CURRENT_TIMESTAMP,duration_ms=? WHERE organization_id=? AND id=? AND status='RUNNING'",(System.nanoTime()-started)/1000000,org,execution)!=1)throw new RestFailure("REST_CANCELLED");if(action.equals("TEST"))db.update("UPDATE app.rest_connector SET health='HEALTHY' WHERE organization_id=? AND id=? AND configuration_version=?",org,id,r.version);return Map.of("result",result,"untrusted",true,"correlationId",execution,"revision",r.version,"protocol","2025-11-25","durationMs",(System.nanoTime()-started)/1000000);}
  }catch(Exception e){String code=e instanceof RestFailure f?f.code:e instanceof AccessDeniedException?"REST_ACCESS_DENIED":"REST_UNAVAILABLE";db.update("UPDATE app.rest_event SET status='FAILED',error_code=?,ended_at=CURRENT_TIMESTAMP,duration_ms=? WHERE organization_id=? AND id=? AND status='RUNNING'",code,(System.nanoTime()-started)/1000000,org,execution);if(Set.of("REST_NETWORK_ERROR","REST_TIMEOUT","REST_TLS_FAILED","REST_AUTHENTICATION_FAILED","REST_FORBIDDEN").contains(code))db.update("UPDATE app.rest_connector SET health=? WHERE organization_id=? AND id=? AND configuration_version=? AND state NOT IN('DISABLED','REVOKED')",code.equals("REST_AUTHENTICATION_FAILED")?"AUTHENTICATION_FAILED":"UNREACHABLE",org,id,r.version);throw new RestFailure(code);}
 }
 public Map<String,Object> tools(UUID actor,UUID org,UUID id){roles(actor,org);var r=revision(org,id);return Map.of("tools",gateway.tools(assertions.issue(actor,org,id,r.version,"LIST",UUID.randomUUID(),null,"")),"protocol","2025-11-25");}
 public Map<String,Object> cancel(UUID actor,UUID org,UUID id,UUID execution){var roles=roles(actor,org);revision(org,id);synchronized(lock(org,id)){if(db.update("UPDATE app.rest_event SET status='CANCELLED',error_code='REST_CANCELLED',ended_at=CURRENT_TIMESTAMP WHERE organization_id=? AND connector_id=? AND id=? AND status='RUNNING' AND (actor=? OR ?)",org,id,execution,actor,roles.contains("INTEGRATION_ADMIN"))==1)gateway.cancel(org,id,execution);}return Map.of("cancelled",true);}
 public Map<String,Object> catalog(){return Map.of("active",db.queryForObject("SELECT EXISTS(SELECT 1 FROM app.rest_connector i JOIN app.rest_operation o ON o.organization_id=i.organization_id AND o.connector_id=i.id AND o.version=i.configuration_version JOIN app.rest_approval a ON a.organization_id=o.organization_id AND a.operation_id=o.id AND a.fingerprint=o.fingerprint WHERE i.state='ACTIVE' AND i.health='HEALTHY' AND o.supported AND a.status='APPROVED')",Boolean.class));}
 private void event(UUID actor,UUID org,UUID id,long version,UUID operation,String kind,String status,String error){db.update("INSERT INTO app.rest_event(organization_id,connector_id,id,actor,version,operation_id,kind,status,error_code,ended_at) VALUES(?,?,?,?,?,?,?,?,?,CURRENT_TIMESTAMP)",org,id,UUID.randomUUID(),actor,version,operation,kind,status,error);}
}
